import{_ as n,o as a,c as o,a0 as l}from"./chunks/framework.DqMqoJl9.js";const d=JSON.parse('{"title":"安装和启动配置","description":"","frontmatter":{},"headers":[],"relativePath":"mongodb/1_install.md","filePath":"mongodb/1_install.md","lastUpdated":1791573371000}'),e={name:"mongodb/1_install.md"};function p(r,s,t,c,i,b){return a(),o("div",null,[...s[0]||(s[0]=[l(`<h1 id="安装和启动配置" tabindex="-1">安装和启动配置 <a class="header-anchor" href="#安装和启动配置" aria-label="Permalink to &quot;安装和启动配置&quot;">​</a></h1><h2 id="_1-安装" tabindex="-1">1 安装 <a class="header-anchor" href="#_1-安装" aria-label="Permalink to &quot;1 安装&quot;">​</a></h2><p>安装参考下面文章：</p><p>(<a href="https://www.runoob.com/mongodb/mongodb-window-install.html" target="_blank" rel="noreferrer">https://www.runoob.com/mongodb/mongodb-window-install.html</a>)[<a href="https://www.runoob.com/mongodb/mongodb-window-install.html" target="_blank" rel="noreferrer">https://www.runoob.com/mongodb/mongodb-window-install.html</a>]</p><p>GUI 管理工具：</p><ul><li>MongoDB Compass 官方推出的工具，(<a href="https://www.mongodb.com/download-center/compass" target="_blank" rel="noreferrer">https://www.mongodb.com/download-center/compass</a>)[<a href="https://www.mongodb.com/download-center/compass" target="_blank" rel="noreferrer">https://www.mongodb.com/download-center/compass</a>]</li><li>Robo 3T (<a href="https://robomongo.org/" target="_blank" rel="noreferrer">https://robomongo.org/</a>)[<a href="https://robomongo.org/" target="_blank" rel="noreferrer">https://robomongo.org/</a>]</li></ul><h2 id="_2-启动配置" tabindex="-1">2 启动配置 <a class="header-anchor" href="#_2-启动配置" aria-label="Permalink to &quot;2 启动配置&quot;">​</a></h2><p>建如下目录：</p><ul><li>data 数据库存储目录</li><li>logs 日志文件存储目录</li><li>mongo.conf 启动的配置文件</li></ul><p>在 mongo.conf 中做如下配置：</p><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#6A737D;"># 数据库路径</span></span>
<span class="line"><span style="color:#24292E;">dbpath</span><span style="color:#D73A49;">=</span><span style="color:#032F62;">/Users/chiu/work/mongodb/data/</span></span>
<span class="line"></span>
<span class="line"><span style="color:#6A737D;"># 日志文件路径</span></span>
<span class="line"><span style="color:#24292E;">logpath</span><span style="color:#D73A49;">=</span><span style="color:#032F62;">/users/chiu/work/mongodb/logs/mongo.log</span></span>
<span class="line"></span>
<span class="line"><span style="color:#6A737D;"># 是否启用日志文件，默认启用</span></span>
<span class="line"><span style="color:#24292E;">journal</span><span style="color:#D73A49;">=</span><span style="color:#032F62;">true</span></span>
<span class="line"></span>
<span class="line"><span style="color:#6A737D;"># 这个选项可以过滤掉一些无用的日志信息</span></span>
<span class="line"><span style="color:#24292E;">quiet</span><span style="color:#D73A49;">=</span><span style="color:#032F62;">true</span></span>
<span class="line"></span>
<span class="line"><span style="color:#6A737D;"># 端口号，默认为 27017</span></span>
<span class="line"><span style="color:#24292E;">port</span><span style="color:#D73A49;">=</span><span style="color:#032F62;">27017</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br></div></div><p>指定 mongo.conf 为配置文件，启动数据库</p><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#6F42C1;">/Users/chiu/work/mongodb/mongodb/bin/mongod</span><span style="color:#005CC5;"> --config</span><span style="color:#032F62;"> /Users/chiu/work/mongodb/mongo.conf</span><span style="color:#005CC5;"> --auth</span></span>
<span class="line"></span>
<span class="line"><span style="color:#6A737D;"># --config 指定配置文件</span></span>
<span class="line"><span style="color:#6A737D;"># --auth 开启认证 (需要使用账号密码)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div>`,13)])])}const u=n(e,[["render",p]]);export{d as __pageData,u as default};
